repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('mia', 37), ('pia', 24), ('noor', 48), ('noor', 58), ('noor', 9)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.finder.py:
"""Finding donations by donor."""


def donations_for(donations, donor):
    """Return the donations whose donor matches, ignoring upper and lower case and spaces at either end."""
    return [x for x in donations if x.donor == donor]


def has_donor(donations, donor):
    """Return True when at least one donation matches the donor."""
    return len(donations_for(donations, donor)) > 0


def describe_donation(donation):
    """Return a one-line description of a donation."""
    return "%s: %s" % (donation.donor, donation.pounds)
